// FastCDC chunker: min=64KB, avg=256KB, max=1MB.
// GEAR table: 256 deterministic 64-bit values generated by a seeded LCG.
// Reference: Wen Xia et al., FastCDC, 2016.
// Same table across implementations ensures cross-platform determinism.

const MIN_SIZE = 64 * 1024; // 64 KB
const AVG_SIZE = 256 * 1024; // 256 KB
const MAX_SIZE = 1 * 1024 * 1024; // 1 MB

// MASK_S: prefer cut in [min, avg]: 1/512 probability per byte.
// MASK_L: accept any cut in [avg, max]: 1/2048 probability per byte.
const MASK_S = 0x1ffn; // 9 bits → 1/512
const MASK_L = 0x7ffn; // 11 bits → 1/2048

// Seeded LCG to generate deterministic 64-bit gear values.
// Reference implementation seed from the FastCDC paper.
function makeGear(): bigint[] {
  const gear = new Array(256);
  let seed = 0x6969696969696969n;
  for (let i = 0; i < 256; i++) {
    seed = (seed * 6364136223846793005n + 1442695040888963407n) & 0xffffffffffffffffn;
    gear[i] = seed;
  }
  return gear;
}

const GEAR = makeGear();

export function* chunk(input: Uint8Array): Generator<Uint8Array> {
  let pos = 0;
  while (pos < input.length) {
    const end = findCutPoint(input, pos);
    yield input.subarray(pos, end);
    pos = end;
  }
}

function findCutPoint(buf: Uint8Array, start: number): number {
  const end = Math.min(buf.length, start + MAX_SIZE);
  const minEnd = Math.min(end, start + MIN_SIZE);
  const avgEnd = Math.min(end, start + AVG_SIZE);

  let hash = 0n;
  let i = minEnd;

  // Stricter mask phase: prefer boundary in [min, avg]
  for (; i < avgEnd; i++) {
    hash = (hash << 1n) + GEAR[buf[i]];
    if ((hash & MASK_S) === 0n) return i + 1;
  }

  // Looser mask phase: take any boundary in [avg, max]
  for (; i < end; i++) {
    hash = (hash << 1n) + GEAR[buf[i]];
    if ((hash & MASK_L) === 0n) return i + 1;
  }

  return end;
}
